function renderEvents(){return pageHeader("Events & schedule","Create and manage real Discord Scheduled Events for your community.")+'<div class="grid">'+card("Create a scheduled event","Create a voice-channel event or an external event with a location. Starry needs Manage Events permission.",'<div class="form-grid">'+input("eventName","Event name","","text","Community game night")+input("eventStart","Starts at","","datetime-local")+input("eventEnd","Ends at","","datetime-local")+select("eventType","Event type",[["external","External / in-person"],["voice","Discord voice channel"]],"external")+ '<div id="eventLocationWrap">'+input("eventLocation","Location","", "text","e.g. Community stage / online")+'</div><div id="eventChannelWrap" hidden>'+select("eventChannel","Voice channel",[["","Choose a voice channel"],...channels("voice")],"")+'</div><div class="field full"><label for="eventDescription">Description</label><textarea id="eventDescription" maxlength="1000" placeholder="What should attendees expect?"></textarea></div></div><div class="actions"><button class="btn primary" id="createEvent">Create Discord event</button></div><div id="eventFeedback"></div>',"full")+card("Scheduled events","Live events fetched directly from Discord.",'<div id="eventList" class="muted"><div class="empty">Loading scheduled events…</div></div>',"full")+'</div>'}
function renderWelcome(){const w=settings.welcome||{};return pageHeader("Welcome & onboarding","Design the welcome card Starry sends when a new member joins your server.")+'<div class="grid">'+card("Welcome message","Choose a text channel and customize the existing welcome engine. Variables: {user}, {username}, {tag}, {server}, {count}.",'<div class="form-grid">'+select("welcomeChannel","Welcome channel",[["","Choose a text channel"],...channels("text")],w.channelId||"")+input("welcomeTitle","Embed title",w.title||"✨ WELCOME TO {server} ✨")+ '<div class="field full"><label for="welcomeDescription">Welcome description</label><textarea id="welcomeDescription" maxlength="4000">'+esc(w.description||"💖 Hello {user}! We are so overjoyed to have you join our family! 🌟")+'</textarea></div>'+input("welcomePing","Message above the embed",w.pingContent||"💫 Welcome {user}! Grab a seat and enjoy your stay! 🥂")+input("welcomeColor","Embed color",w.color||"#FF73FA","color")+input("welcomeFooter","Embed footer",w.footer||"✨ Enjoy your stellar journey in {server}! ✨")+input("welcomeImage","Banner image / GIF URL",w.image||"","url","https://…")+input("welcomeThumbnail","Thumbnail URL or avatar",w.thumbnail||"avatar","text","avatar or https://…")+'</div><div class="actions"><button class="btn primary" id="saveWelcome">Save welcome settings</button></div><div id="welcomeFeedback"></div><div class="status">Saving here updates the same MongoDB settings used by Starry’s existing guildMemberAdd welcome handler. The selected channel must be a text channel.</div>',"full")+'</div>'}
