async function loadEvents(){const list=$("#eventList");try{const d=await request("/api/guild/"+guildId+"/events");if(!d.events?.length){list.innerHTML='<div class="empty">No scheduled events yet.</div>';return}list.innerHTML=d.events.map(e=>'<div class="check-row"><div><strong>'+esc(e.name)+'</strong><small>'+esc(e.description||"No description")+' · '+(e.entityType===2?"Voice event": "External event")+'</small><small>'+esc(e.start?new Date(e.start).toLocaleString():"Time unavailable")+' → '+esc(e.end?new Date(e.end).toLocaleString():"")+(e.location?" · "+esc(e.location):"")+'</small></div><button class="btn danger" data-cancel-event="'+esc(e.id)+'">Cancel</button></div>').join("");list.querySelectorAll("[data-cancel-event]").forEach(button=>button.addEventListener("click",async()=>{if(!confirm("Cancel this Discord scheduled event?"))return;try{const result=await request("/api/guild/"+guildId+"/events/"+encodeURIComponent(button.dataset.cancelEvent),{method:"DELETE"});$("#eventFeedback").innerHTML=status(result.message,"good");loadEvents()}catch(error){$("#eventFeedback").innerHTML=status(error.message,"bad")}}))}catch(e){list.innerHTML=status(e.message,"bad")}}
