$("#saveTickets")?.addEventListener("click",()=>saveGroup("tickets",{enabled:"bool",categoryId:"text",supportRoleId:"text",panelChannelId:"text",transcriptsChannel:"text"}));
$("#eventType")?.addEventListener("change",()=>{const voice=$("#eventType").value==="voice";$("#eventLocationWrap").hidden=voice;$("#eventChannelWrap").hidden=!voice});
$("#createEvent")?.addEventListener("click",async()=>{const body={name:$("#eventName").value,description:$("#eventDescription").value,type:$("#eventType").value,start:new Date($("#eventStart").value).toISOString(),end:new Date($("#eventEnd").value).toISOString(),location:$("#eventLocation").value,channelId:$("#eventChannel").value};try{const d=await request("/api/guild/"+guildId+"/events",{method:"POST",body:JSON.stringify(body)});$("#eventFeedback").innerHTML=status(d.message||"Event created.","good");$("#eventName").value="";$("#eventDescription").value="";loadEvents()}catch(e){$("#eventFeedback").innerHTML=status(e.message,"bad")}});
$("#saveWelcome")?.addEventListener("click",async()=>{try{const d=await request("/api/guild/"+guildId+"/welcome",{method:"POST",body:JSON.stringify({channelId:$("#welcomeChannel").value,title:$("#welcomeTitle").value,description:$("#welcomeDescription").value,pingContent:$("#welcomePing").value,color:$("#welcomeColor").value,footer:$("#welcomeFooter").value,image:$("#welcomeImage").value,thumbnail:$("#welcomeThumbnail").value})});settings.welcome=d.settings||settings.welcome;$("#welcomeFeedback").innerHTML=status(d.message||"Welcome settings saved.","good")}catch(e){$("#welcomeFeedback").innerHTML=status(e.message,"bad")}});
$("#saveLeveling")?.addEventListener("click",async()=>{try{const d=await request("/api/guild/"+guildId+"/leveling/settings",{method:"POST",body:JSON.stringify({enabled:$("#levelEnabled").checked,logChannelId:$("#levelLogChannel").value,title:$("#levelTitle").value,description:$("#levelDescription").value,color:$("#levelColor").value})});settings.leveling=d.settings||settings.leveling;$("#levelFeedback").innerHTML=status(d.message||"Leveling settings saved.","good")}catch(e){$("#levelFeedback").innerHTML=status(e.message,"bad")}});
$("#saveGeneral")?.addEventListener("click",async()=>{const prefix=$("#prefix").value.trim(),triggerWord=$("#triggerWord").value.trim();if(prefix.length<1||prefix.length>3){feedback("Command prefix must contain 1 to 3 characters.","bad");return}if(!triggerWord||triggerWord.length>32){feedback("Trigger word must contain 1 to 32 characters.","bad");return}try{const d=await request("/api/guild/"+guildId+"/settings",{method:"POST",body:JSON.stringify({prefix,triggerWord})});settings=d.settings||settings;feedback("General settings saved.","good")}catch(e){feedback(e.message,"bad")}});
