$("#runMod")?.addEventListener("click",async()=>{const body={action:$("#action").value,targetId:$("#targetId").value.trim(),reason:$("#reason").value.trim(),durationMinutes:Number($("#durationMinutes").value),roleId:$("#roleId").value.trim(),nickname:$("#nickname").value.trim()};try{const d=await request("/api/guild/"+guildId+"/mod/action",{method:"POST",body:JSON.stringify(body)});feedback(d.message||"Action completed.","good")}catch(e){feedback(e.message,"bad")}});
$("#spotifySearchBtn")?.addEventListener("click",async()=>{const q=$("#spotifySearchQuery").value.trim();const host=$("#spotifySearchResults");if(!q){host.innerHTML=status("Enter a song, artist or supported music URL.","bad");return}const btn=$("#spotifySearchBtn");btn.disabled=true;btn.textContent="Searching…";host.innerHTML='<div class="empty">Searching connected music sources…</div>';try{const d=await request("/api/guild/"+guildId+"/music/search?q="+encodeURIComponent(q));host.innerHTML=(d.tracks||[]).map(t=>'<div class="spotify-result-row"><img src="'+esc(t.artwork||"https://cdn.discordapp.com/embed/avatars/0.png")+'" alt="" loading="lazy"><div class="spotify-result-copy"><strong>'+esc(t.title)+'</strong><small>'+esc(t.artist)+' · '+formatTrackTime(t.durationMs||0)+' · '+esc(t.source||"Audio source")+'</small></div><button class="btn" data-music-query="'+esc(t.query||t.uri||"")+'">Queue</button></div>').join("")||'<div class="empty">No playable matches found. Try another source or search phrase.</div>';host.querySelectorAll("[data-music-query]").forEach(button=>button.addEventListener("click",async()=>{const query=button.dataset.musicQuery;if(!query)return;button.disabled=true;button.textContent="Adding…";try{const queued=await request("/api/guild/"+guildId+"/music/play",{method:"POST",body:JSON.stringify({query,voiceChannelId:$("#voiceChannelId")?.value||"",textChannelId:$("#textChannelId")?.value||""})});host.insertAdjacentHTML("afterbegin",status(queued.message||"Track queued.","good"));await loadGuild()}catch(error){host.insertAdjacentHTML("afterbegin",status(error.message,"bad"))}finally{button.disabled=false;button.textContent="Queue"}}))}catch(e){host.innerHTML=status(e.message,"bad")}finally{btn.disabled=false;btn.textContent="Search all sources"}});
$("#spotifySearchQuery")?.addEventListener("keydown",e=>{if(e.key==="Enter")$("#spotifySearchBtn")?.click()});
$("#playMusic")?.addEventListener("click",async()=>{const query=$("#query").value.trim();if(!query){$("#playFeedback").innerHTML=status("Enter a song name or URL first.","bad");return}const button=$("#playMusic");button.disabled=true;button.textContent="Adding…";try{const d=await request("/api/guild/"+guildId+"/music/play",{method:"POST",body:JSON.stringify({query,voiceChannelId:$("#voiceChannelId").value,textChannelId:$("#textChannelId").value})});$("#playFeedback").innerHTML=status(d.message||"Track queued.","good");await loadGuild();renderPage()}catch(e){$("#playFeedback").innerHTML=status(e.message,"bad")}finally{button.disabled=false;button.textContent="Add track ＋"}});
document.querySelectorAll("[data-control]").forEach(b=>b.onclick=async()=>{try{const d=await request("/api/guild/"+guildId+"/music/control",{method:"POST",body:JSON.stringify({action:b.dataset.control})});feedback(d.message,"good");await loadGuild()}catch(e){feedback(e.message,"bad")}});
$("#volume")?.addEventListener("input",()=>{$("#volumeValue").textContent=$("#volume").value+"%"});$("#refreshMusicQueue")?.addEventListener("click",async()=>{try{await loadGuild();renderPage()}catch(e){feedback(e.message,"bad")}});$("#query")?.addEventListener("keydown",e=>{if(e.key==="Enter")$("#playMusic")?.click()});$("#refreshMusic")?.addEventListener("click",async()=>{await loadGuild();renderPage()});$("#applyMusic")?.addEventListener("click",async()=>{const controls=[["volume",Number($("#volume").value)],["filter",$("#filter").value],["loop",$("#loop").value],["autoplay",$("#autoplay").value==="on"],["toggle247",$("#is247").checked]];for(const [action,value] of controls){try{await request("/api/guild/"+guildId+"/music/control",{method:"POST",body:JSON.stringify({action,value})})}catch(e){feedback(e.message,"bad");return}}feedback("Music settings updated.","good");await loadGuild();renderPage()});
$("#saveEmbedTheme")?.addEventListener("click",async()=>{const body={embedTheme:{color:$("#color").value,authorName:$("#author").value.trim(),authorIcon:$("#authorIcon").value.trim(),footer:$("#footer").value.trim(),footerIcon:$("#footerIcon").value.trim()}};try{const d=await request("/api/guild/"+guildId+"/settings",{method:"POST",body:JSON.stringify(body)});settings=d.settings||settings;feedback("Server-wide embed identity saved.","good")}catch(e){feedback(e.message,"bad")}});$("#sendEmbed")?.addEventListener("click",async()=>{const body={channelId:$("#channelId").value,title:$("#title").value,description:$("#description").value,color:$("#color").value,author:$("#author").value,authorIcon:$("#authorIcon").value,thumbnail:$("#thumbnail").value,image:$("#image").value,footer:$("#footer").value,footerIcon:$("#footerIcon").value};try{const d=await request("/api/guild/"+guildId+"/embed/send",{method:"POST",body:JSON.stringify(body)});feedback(d.message,"good")}catch(e){feedback(e.message,"bad")}});
$("#saveBooster")?.addEventListener("click",async()=>{try{const info=await request("/api/guild/"+guildId+"/booster-roles");const path=info.myRole?"update":"create";const d=await request("/api/guild/"+guildId+"/booster-roles/"+path,{method:"POST",body:JSON.stringify({name:$("#roleName").value.trim(),color:$("#roleColor").value})});feedback(d.message,"good");loadBoosterInfo()}catch(e){feedback(e.message,"bad")}});
